// Extract Caller ID and sanitize phone number
const body = $input.first().json.body || $input.first().json;
const rawPhone = body.From || body.caller_number || body.phone || '';
const cleanedPhone = rawPhone.replace(/[^+\d]/g, '');
const callStatus = body.CallStatus || body.event || 'no-answer';

// Basic suppression check (in-memory or static list evaluation)
const optOutList = ['+15550000000']; // Populated dynamically in production
const isOptedOut = optOutList.includes(cleanedPhone);

return [{
  json: {
    rawPhone,
    cleanedPhone,
    callStatus,
    isOptedOut,
    timestamp: new Date().toISOString()
  }
}];

// Business Hours Evaluator (Mon-Fri 8am-6pm local time)
const now = new Date();
const day = now.getDay(); // 0 = Sun, 6 = Sat
const hour = now.getHours(); // 0-23

let isBusinessHours = false;
if (day >= 1 && day <= 5) {
  if (hour >= 8 && hour < 18) {
    isBusinessHours = true;
  }
}

return [{
  json: {
    ...$input.first().json,
    isBusinessHours,
    evaluatedAt: now.toISOString()
  }
}];

