// Extract generated text from DeepSeek response
const response = $input.first().json;
let smsContent = '';
if (response.choices && response.choices.length > 0) {
  smsContent = response.choices[0].message.content.trim();
} else {
  // Fallback template
  smsContent = "Hey! On a job site & missed your call. How can we help with your project? Reply STOP to cancel.";
}

// Ensure length < 160 chars
if (smsContent.length > 160) {
  smsContent = smsContent.substring(0, 155) + " STOP";
}

return [{
  json: {
    toPhone: $('Code - Business Hours Evaluator').first().json.cleanedPhone,
    smsBody: smsContent
  }
}];

// Detect Opt-Out Keywords
const body = $input.first().json.body || $input.first().json;
const fromPhone = (body.From || '').replace(/[^+\d]/g, '');
const smsBody = (body.Body || '').toUpperCase().trim();

const optOutKeywords = ['STOP', 'UNSUBSCRIBE', 'CANCEL', 'QUIT', 'END'];
const isOptOutAction = optOutKeywords.some(keyword => smsBody.includes(keyword));

return [{
  json: {
    fromPhone,
    smsBody,
    isOptOutAction,
    action: isOptOutAction ? 'ADD_TO_SUPPRESSION_LIST' : 'NONE'
  }
}];
